          { consecutiveFails: { gt: 0 }, probeStatus: { not: "DEAD" }, lastProbeAt: { lt: cutoff(FAIL_RETRY_MS) } },
          { consecutiveFails: 0, probeStatus: { not: "DEAD" }, lastProbeAt: { lt: cutoff(ALIVE_REPROBE_MS) } },
