 * Directory liveness rules. PURE (no db, no network, no clock except what is passed in) and
 * unit-tested (test/directory-liveness.test.ts). The network half is lib/directory-ingest/a2s.ts;
 * the database + pacing half is lib/directory-ingest/prober.ts.
 *
 * What the prober may touch: stored `ExternalServer` rows that came from the Steam list, i.e.
 * addresses we were GIVEN. There is no scanning of address space, no discovery, and no
 * player-level data (see a2s.ts). Bounds, all enforced here or in prober.ts:
 *   - about PROBE_RATE_PER_SEC probes per second overall, PROBE_CONCURRENCY in flight at most
 *   - per tick: at most PER_IP_PER_TICK probes to one IP and PER_SUBNET_PER_TICK to one /24
 *     (hosting companies run dozens of servers on one address; per-host politeness)
 *   - only public IPv4 addresses on ports >= 1024, never a well-known service port
 *   - a row is declared DEAD only after DEAD_AFTER_FAILS consecutive failed probes
 */

export const PROBE_RATE_PER_SEC = 10;
export const PROBE_CONCURRENCY = 64;
export const PER_IP_PER_TICK = 2;
export const PER_SUBNET_PER_TICK = 30;
export const DEAD_AFTER_FAILS = 3;

