/** A live row is re-probed this often; its player counts stay under the 60 minute "live" limit. */
export const ALIVE_REPROBE_MS = 30 * MIN;
/** A row that just failed is retried quickly so a blip does not linger and a real outage reaches DEAD in ~30 min. */
export const FAIL_RETRY_MS = 10 * MIN;
/** A DEAD row (hidden) is re-checked once a day in case it came back. */
export const DEAD_REPROBE_MS = 24 * 60 * MIN;
/** A number older than this is never presented as "playing now". */
export const FRESH_COUNT_MS = 60 * MIN;
/** With the prober ON, a row must have answered within this window to be shown at all. */
export const ALIVE_VISIBLE_MS = 24 * 60 * MIN;
/** A tick where this many probes ran and none answered is treated as OUR network being broken, not 20 dead servers. */
export const BLACKOUT_MIN_PROBES = 20;

export type ProbeStatus = "UNKNOWN" | "ALIVE" | "DEAD";

export type ProbeRow = {
  id: string;
  ip: string | null;
  port: number;
  queryPort: number | null;
  game: string;
  probeStatus: string;
  consecutiveFails: number;
  lastProbeAt: Date | null;
