/** When this row is next due, as ms epoch (0 = now). */
export function dueAt(r: ProbeRow): number {
  if (!r.lastProbeAt) return 0;
  const last = r.lastProbeAt.getTime();
  if (r.probeStatus === "DEAD") return last + DEAD_REPROBE_MS;
  if (r.consecutiveFails > 0) return last + FAIL_RETRY_MS;
  return last + ALIVE_REPROBE_MS;
}

/** 0 = never probed, 1 = failing (settle it), 2 = routine re-probe, 3 = dead re-check. */
function priority(r: ProbeRow): number {
  if (!r.lastProbeAt) return 0;
  if (r.probeStatus === "DEAD") return 3;
  return r.consecutiveFails > 0 ? 1 : 2;
}

const subnet = (ip: string) => ip.split(".").slice(0, 3).join(".");

/**
 * Pick this tick's batch from candidate rows: due rows only, new/failing first, then the
 * longest-waiting; bounded in total and per IP and per /24. Rows that cannot be probed are skipped.
 */
export function selectProbeBatch(
  rows: ProbeRow[], now: number,
  opts: { batch: number; perIp?: number; perSubnet?: number },
): ProbeRow[] {
  const perIp = opts.perIp ?? PER_IP_PER_TICK, perSubnet = opts.perSubnet ?? PER_SUBNET_PER_TICK;
  const due = rows
    .filter((r) => dueAt(r) <= now && probeTarget(r))
    .sort((a, b) => priority(a) - priority(b) || (a.lastProbeAt?.getTime() ?? 0) - (b.lastProbeAt?.getTime() ?? 0));
  const ip = new Map<string, number>(), net = new Map<string, number>();
  const out: ProbeRow[] = [];
  for (const r of due) {
    if (out.length >= opts.batch) break;
    const i = r.ip!, s = subnet(i);
    if ((ip.get(i) ?? 0) >= perIp || (net.get(s) ?? 0) >= perSubnet) continue;
    ip.set(i, (ip.get(i) ?? 0) + 1);
    net.set(s, (net.get(s) ?? 0) + 1);
    out.push(r);
  }
  return out;
}

export type ProbeOutcome =
  | { alive: true; rttMs: number; players: number; maxPlayers: number; viaSplit?: boolean }
  | { alive: false; reason: string };

export type ProbeUpdate = {
  probeStatus: ProbeStatus;
  consecutiveFails: number;
  lastProbeAt: Date;
  lastAliveAt: Date | null;
  latencyMs: number | null;
  /** Fresh counts from the server itself; absent when the probe could not read them. */
  players?: number;
  maxPlayers?: number;
};

/** The state machine: success -> ALIVE with zero failures; a failure counts, and DEAD_AFTER_FAILS in a row = DEAD. */
export function nextProbeState(
  prev: Pick<ProbeRow, "probeStatus" | "consecutiveFails" | "lastAliveAt">, o: ProbeOutcome, now: Date,
): ProbeUpdate {
  if (o.alive) {
    const counts = !o.viaSplit && o.maxPlayers > 0 ? { players: o.players, maxPlayers: o.maxPlayers } : {};
    return { probeStatus: "ALIVE", consecutiveFails: 0, lastProbeAt: now, lastAliveAt: now, latencyMs: Math.min(o.rttMs, 60_000), ...counts };
  }
  const fails = prev.consecutiveFails + 1;
  const status: ProbeStatus = fails >= DEAD_AFTER_FAILS ? "DEAD" : prev.probeStatus === "ALIVE" ? "ALIVE" : "UNKNOWN";
  return { probeStatus: status, consecutiveFails: fails, lastProbeAt: now, lastAliveAt: prev.lastAliveAt, latencyMs: null };
}

/** A whole tick with enough probes and zero answers means our own egress is broken: record nothing. */
export function isProbeBlackout(results: { alive: boolean }[]): boolean {
  return results.length >= BLACKOUT_MIN_PROBES && !results.some((r) => r.alive);
}

export type PublicRow = {
  probeStatus: string;
  lastAliveAt: Date | null;
  lastSeenAt: Date;
  lastProbeAt?: Date | null;
};

/**
 * May this stored row appear on a public page? DEAD never. With the prober OFF an unprobed row is
 * shown on the strength of the Steam list alone (labelled "seen on the list", not "checked"); with the
 * prober ON a row must have ANSWERED us within ALIVE_VISIBLE_MS: nothing unverified is presented as live.
 */
export function isRowPublic(r: PublicRow, opts: { probeOn: boolean; now?: number }): boolean {
  if (r.probeStatus === "DEAD") return false;
  if (!opts.probeOn) return true;
  const now = opts.now ?? Date.now();
  return r.probeStatus === "ALIVE" && !!r.lastAliveAt && now - r.lastAliveAt.getTime() <= ALIVE_VISIBLE_MS;
}

/** Player counts are only shown as live when the newest source of them (list refresh or probe) is under an hour old. */
export function liveCountsFresh(r: Pick<PublicRow, "lastAliveAt" | "lastSeenAt">, now = Date.now()): boolean {
  const newest = Math.max(r.lastSeenAt.getTime(), r.lastAliveAt?.getTime() ?? 0);
  return now - newest <= FRESH_COUNT_MS;
}

