const FLAGS = ["directory_ingest_enabled", "directory_external_show", "directory_sweep_enabled", "directory_probe_enabled"] as const;
/** Flags that put Steam data on the site or start pulling it: the legal checkpoints must be recorded first. */
const LEGAL_GATED = new Set<string>(["directory_ingest_enabled", "directory_external_show", "directory_sweep_enabled"]);
export async function adminSetDirectoryFlag(key: (typeof FLAGS)[number], value: boolean): Promise<Result> {
  const admin = await requireArea("fleet");
  if (!FLAGS.includes(key)) return { ok: false, error: "Unknown setting." };
  const { setSetting, getSetting } = await import("./settings");
  if (value && LEGAL_GATED.has(key)) {
    const { steamLegalGate } = await import("./directory-steam");
    const problems = steamLegalGate({
      storageCountry: await getSetting("directory_storage_country", ""),
      termsReviewedBy: await getSetting("directory_steam_terms_reviewed_by", ""),
    });
    if (problems.length) return { ok: false, error: problems.join(" ") };
  }
  await setSetting(key, value ? "true" : "false");
  await recordAudit(admin.id, "directory.flag", `${key}=${value}`);
  revalidatePath("/admin/directory");
  revalidatePath("/game-servers/directory");
  return { ok: true };
}

/** The two legal checkpoints (storage country, who read the Steam terms) and the sweep's base interval. */
export async function adminSaveSteamConfig(input: { storageCountry: string; termsReviewedBy: string; intervalMin: number }): Promise<Result> {
  const admin = await requireArea("fleet");
  const country = String(input.storageCountry ?? "").replace(/\s+/g, " ").trim();
  const by = String(input.termsReviewedBy ?? "").replace(/\s+/g, " ").trim();
  if (country.length > 60 || by.length > 120) return { ok: false, error: "Too long." };
  const { setSetting } = await import("./settings");
  const { clampIntervalMin } = await import("./directory-ingest/schedule");
  await setSetting("directory_storage_country", country);
  await setSetting("directory_steam_terms_reviewed_by", by);
  await setSetting("directory_sweep_interval_minutes", String(clampIntervalMin(Number(input.intervalMin))));
  await recordAudit(admin.id, "directory.steam.config", `country=${country || "-"} reviewedBy=${by || "-"} interval=${clampIntervalMin(Number(input.intervalMin))}`);
  revalidatePath("/admin/directory");
  return { ok: true };
}

/** "Run now": the next worker tick refreshes every game once, ignoring the schedule (kill switches, gates, breaker and budget still apply). */
export async function adminRequestSteamSweep(): Promise<Result> {
  const admin = await requireArea("fleet");
  try {
    await db.directorySource.upsert({ where: { key: "steam" }, create: { key: "steam", runRequested: true }, update: { runRequested: true } });
    await recordAudit(admin.id, "directory.steam.run-now", "");
    revalidatePath("/admin/directory");
    return { ok: true };
  } catch { return { ok: false, error: "Could not save." }; }
}

/** Close the breaker and clear the backoff after the cause (key, outage) was dealt with. */
export async function adminResetSteamBreaker(): Promise<Result> {
  const admin = await requireArea("fleet");
  try {
    await db.directorySource.update({ where: { key: "steam" }, data: { circuitOpenUntil: null, nextAttemptAt: null, consecutiveErrors: 0 } });
    await recordAudit(admin.id, "directory.steam.reset-breaker", "");
    revalidatePath("/admin/directory");
    return { ok: true };
  } catch { return { ok: false, error: "Nothing to reset yet." }; }
}

