            <span className="text-rim-hi">|</span>
            <Link href="/dashboard/services" className="font-semibold text-brand-300 transition hover:text-white">
              List your own server
            </Link>
          </p>
        </div>
      </header>

      {/* ── filters ───────────────────────────────────────────────────── */}
      <div className="flex flex-wrap items-center gap-2.5">
        <span className="flex h-[40px] min-w-[220px] flex-1 items-center gap-2.5 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3.5">
