import { ProviderFetchError } from "./types";

/**
 * One polite JSON GET. An honest User-Agent that says who we are and how to reach us, a timeout, a body-size
 * ceiling (never buffer an unbounded answer), ETag revalidation so an unchanged list costs a 304, and a
 * ProviderFetchError carrying the HTTP status and Retry-After so the shared breaker can react. It never
 * retries by itself: retry/backoff is the scheduler's job (a failure backs the whole source off).
 */
export const DIRECTORY_UA = "NxeonDirectory/2.0 (+https://nxeon.cloud/game-servers/directory; abuse@nxeon.cloud)";

export async function politeGetJson(url: string, opts: { fetchImpl?: typeof fetch; etag?: string | null; timeoutMs?: number; maxBytes?: number } = {}): Promise<{ json: unknown; etag: string | null; notModified: boolean }> {
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), opts.timeoutMs ?? 60_000);
  try {
    const headers: Record<string, string> = { accept: "application/json", "user-agent": DIRECTORY_UA };
    if (opts.etag) headers["if-none-match"] = opts.etag;
    const res = await (opts.fetchImpl ?? fetch)(url, { signal: ctl.signal, headers });
    if (res.status === 304) return { json: null, etag: opts.etag ?? null, notModified: true };
    if (!res.ok) {
      const ra = Number(res.headers?.get?.("retry-after"));
      throw new ProviderFetchError(`answered HTTP ${res.status}`, res.status, Number.isFinite(ra) && ra > 0 ? ra : undefined);
    }
    const text = await res.text();
    if (text.length > (opts.maxBytes ?? 25_000_000)) throw new ProviderFetchError("answer too large");
    let json: unknown;
    try { json = JSON.parse(text); } catch { throw new ProviderFetchError("answer was not JSON"); }
    return { json, etag: res.headers?.get?.("etag") ?? null, notModified: false };
  } catch (e) {
    if (e instanceof ProviderFetchError) throw e;
    throw new ProviderFetchError(e instanceof Error && e.name === "AbortError" ? "request timed out" : "request failed");
