import { judgeCandidates, splitDuplicates, type PtrCache } from "./run";
import { isSuspiciousShrink } from "./schedule";
import { countryFromIp } from "@/lib/geo-ip";
import type { RuleSet } from "@/lib/directory-blocklist";
import type { ReverseFn } from "./ptr";
import type { DirectoryProvider, ProviderCandidate } from "./providers/types";

/**
 * The shared, PURE half of a provider run: candidates in, a write plan out. No database, no network (reverse DNS
 * is injected), so it is unit-tested with fakes (test/directory-providers.test.ts). provider-run.ts executes the plan.
 *
 * Order of rules, the same for every source:
 *   1. drop anything colliding with a server Nxeon hosts, or already held by ANOTHER source (the directory
 *      shows one row per connection; Steam's A2S-verified row wins over a later listing)
 *   2. competitor-host blocklist (rows are stored with a verdict, never silently lost)
 *   3. country from the local geoip database when the source gives none (no network)
 *   4. a list that shrank sharply against what we hold is "suspicious": refresh, prune nothing
 */
export type ExistingRow = { id: string; sourceKey: string; host: string; ptrName: string | null; ptrCheckedAt: Date | null; lastSeenAt: Date };

export type PlannedWrite = { create: boolean; sourceKey: string; data: Record<string, unknown> };

export type ProviderPlan = {
  writes: PlannedWrite[];
  duplicates: number;
  blocked: number;
  suspicious: boolean;
  /** Delete rows of this source not seen since this instant (null = prune nothing this run). */
  pruneBefore: Date | null;
  /** Delete rows of this source whose connection now collides with a server Nxeon hosts. */
  dropKeys: string[];
};

export async function buildProviderPlan(i: {
  provider: DirectoryProvider; candidates: ProviderCandidate[]; existing: ExistingRow[];
  nxeonKeys: Set<string>; otherSourceKeys: Set<string>; rules: RuleSet; now: Date; reverse?: ReverseFn;
}): Promise<ProviderPlan> {
  const { provider, now } = i;
  const taken = new Set([...i.nxeonKeys, ...i.otherSourceKeys]);
  const { keep, dup } = splitDuplicates(i.candidates, taken);
  const cache: PtrCache = new Map(i.existing.map((r) => [r.host, { ptrName: r.ptrName, checkedAt: r.ptrCheckedAt }]));
  const judged = await judgeCandidates(keep, i.rules, cache, { reverse: i.reverse, now });
  const existing = new Set(i.existing.map((r) => r.sourceKey));
  const writes: PlannedWrite[] = judged.map(({ cand: c, ptrName, ptrCheckedAt, blockedReason, blockedRule }) => {
    const alive = c.alive === true;
    const data: Record<string, unknown> = {
      blockedReason, blockedRule, ptrName, ptrCheckedAt, source: provider.key, attribution: provider.attribution.key,
      probeKind: provider.probeKindFor(c.game),
      game: c.game, name: c.name, host: c.host, ip: c.ip, port: c.port, queryPort: c.queryPort, map: c.map,
      country: c.country ?? (c.ip ? countryFromIp(c.ip) : null),
      players: c.players, maxPlayers: c.maxPlayers, version: c.version, tags: c.tags,
      connKey: c.connKey, ipKey: c.ipKey, lastSeenAt: now,
    };
    // A listing source's own heartbeat is the liveness evidence: listed + up = ALIVE now; listed + down = DEAD (hidden).
    if (provider.probeKindFor(c.game) === "listing") {
      Object.assign(data, alive ? { probeStatus: "ALIVE", lastAliveAt: now, consecutiveFails: 0 } : { probeStatus: "DEAD" });
    }
    return { create: !existing.has(c.sourceKey), sourceKey: c.sourceKey, data };
  });
  const previous = i.existing.filter((r) => now.getTime() - r.lastSeenAt.getTime() < 86_400_000).length;
  const suspicious = isSuspiciousShrink(previous, keep.length);
  return {
    writes, duplicates: dup, blocked: judged.filter((j) => j.blockedReason).length, suspicious,
    pruneBefore: suspicious ? null : new Date(now.getTime() - provider.pruneAfterDays * 86_400_000),
    dropKeys: [...i.nxeonKeys],
  };
}
