export async function runProvider(provider: DirectoryProvider, opts: { etag?: string | null; fetchImpl?: typeof fetch; reverse?: ReverseFn; trigger?: "worker" | "admin" | "cli"; now?: Date } = {}): Promise<ProviderRunResult & { etag: string | null; requests: number }> {
  const now = opts.now ?? new Date();
  const run = await db.directoryIngestRun.create({ data: { source: provider.key, game: provider.games.join(","), trigger: opts.trigger ?? "worker", status: "error" } });
  try {
    const r = await provider.fetch({ fetchImpl: opts.fetchImpl, etag: opts.etag });
    if (r.notModified) {
      // Unchanged list: keep the rows we hold alive (their listing is still current) without re-writing them.
      await db.externalServer.updateMany({ where: { source: provider.key }, data: { lastSeenAt: now } });
      await db.directoryIngestRun.update({ where: { id: run.id }, data: { finishedAt: new Date(), status: "ok", note: "not modified (304)", error: null } });
      return { key: provider.key, fetched: 0, inserted: 0, updated: 0, duplicates: 0, pruned: 0, blocked: 0, suspicious: false, notModified: true, etag: r.etag ?? opts.etag ?? null, requests: r.requests };
    }
    const [nxeonKeys, existing, others] = await Promise.all([
      nxeonConnectionKeys(),
      db.externalServer.findMany({ where: { source: provider.key }, select: { id: true, sourceKey: true, host: true, ptrName: true, ptrCheckedAt: true, lastSeenAt: true } }),
      db.externalServer.findMany({ where: { source: { not: provider.key } }, select: { connKey: true, ipKey: true } }),
    ]);
    const otherSourceKeys = new Set(others.flatMap((o) => [o.connKey, ...(o.ipKey ? [o.ipKey] : [])]));
    const { set } = await loadRuleSet();
    const plan = await buildProviderPlan({ provider, candidates: r.candidates, existing, nxeonKeys, otherSourceKeys, rules: set, now, reverse: opts.reverse });
    const w = await applyPlan(provider, plan, now);
    await db.directoryIngestRun.update({
      where: { id: run.id },
      data: {
        finishedAt: new Date(), fetched: r.candidates.length, inserted: w.inserted, updated: w.updated, duplicates: plan.duplicates, pruned: w.pruned, blocked: plan.blocked,
        status: plan.suspicious ? "suspicious" : "ok",
        note: plan.suspicious ? "List shrank sharply: kept old rows, pruned nothing." : null, error: null,
      },
    });
    return { key: provider.key, fetched: r.candidates.length, inserted: w.inserted, updated: w.updated, duplicates: plan.duplicates, pruned: w.pruned, blocked: plan.blocked, suspicious: plan.suspicious, notModified: false, etag: r.etag ?? null, requests: r.requests };
  } catch (e) {
    const msg = e instanceof Error ? e.message : "ingest failed";
    await db.directoryIngestRun.update({ where: { id: run.id }, data: { finishedAt: new Date(), status: "error", error: redactKey(msg, undefined) } }).catch(() => {});
    throw e;
  }
}

export type ProviderTickReport = { key: string; skipped?: ProviderSkip; result?: ProviderRunResult; error?: string; disabled?: boolean };

export async function directoryProviderTick(opts: { now?: number; fetchImpl?: typeof fetch; envKill?: boolean; providers?: readonly DirectoryProvider[]; reverse?: ReverseFn } = {}): Promise<ProviderTickReport[]> {
  const now = opts.now ?? Date.now();
  const envKill = opts.envKill ?? process.env.DIRECTORY_SWEEP_DISABLED === "1";
  const ingestOn = await getSettingBool("directory_ingest_enabled", false);
  const out: ProviderTickReport[] = [];
  for (const p of opts.providers ?? PROVIDERS) {
    // Cheap exits first: a source that is switched off costs no database writes at all.
    const enabled = await getSettingBool(enableSettingFor(p.key), false);
    if (!enabled || envKill || !ingestOn) { out.push({ key: p.key, skipped: envKill ? "kill-switch" : "disabled" }); continue; }
    const reviewedBy = await getSetting(reviewedSettingFor(p.key), "");
    const src = await ensureSource(p.key);
    const skip = providerGate({
      envKill, ingestOn, enabled, reviewedBy, circuitOpenUntil: src.circuitOpenUntil, nextAttemptAt: src.nextAttemptAt, runningUntil: src.runningUntil,
      lastOkAt: src.lastOkAt, lastRunAt: src.lastRunAt, remainingCalls: callsRemaining(src, now, p.dailyCallCap), intervalMin: p.intervalMin, runRequested: src.runRequested, now,
    });
    if (skip) { out.push({ key: p.key, skipped: skip }); continue; }
    const claimed = await db.directorySource.updateMany({
      where: { key: p.key, OR: [{ runningUntil: null }, { runningUntil: { lt: new Date(now) } }] },
      data: { runningUntil: new Date(now + CLAIM_MS) },
    });
    if (!claimed.count) { out.push({ key: p.key, skipped: "running" }); continue; }
    const prevStats = (src.stats ?? {}) as { etag?: string | null };
    let errors = src.consecutiveErrors, lastOkAt = src.lastOkAt, lastError = src.lastError, lastErrorAt = src.lastErrorAt;
    let circuit: Date | null = null, next: Date | null = null, etag = prevStats.etag ?? null;
    const callsDay = dayKey(now);
    let callsToday = (src.callsDay === callsDay ? src.callsToday : 0) + 1; // counted BEFORE the call
    const rep: ProviderTickReport = { key: p.key };
    try {
      const r = await runProvider(p, { etag, fetchImpl: opts.fetchImpl, reverse: opts.reverse, trigger: src.runRequested ? "admin" : "worker", now: new Date(now) });
      etag = r.etag; errors = 0; lastOkAt = new Date(now); lastError = null; lastErrorAt = null;
      rep.result = r; callsToday += 0;
    } catch (e) {
      const status = e instanceof ProviderFetchError ? e.status : undefined;
      const msg = redactKey(e instanceof Error ? e.message : "fetch failed", undefined);
      errors += 1; lastError = msg; lastErrorAt = new Date(now); rep.error = msg;
      const b = breakerDecision(errors, status);
      next = new Date(now + backoffMs(errors, e instanceof ProviderFetchError ? e.retryAfterSec : undefined));
      if (b.open) circuit = new Date(now + b.openMs);
      if (b.disable) { await setSetting(enableSettingFor(p.key), "false"); rep.disabled = true; console.error(`[directory] ${p.key} answered HTTP ${status}: source switched OFF. Read ${p.termsUrl} before turning it back on.`); }
    } finally {
      await db.directorySource.update({
        where: { key: p.key },
        data: {
          runningUntil: null, runRequested: false, lastRunAt: new Date(now), lastOkAt, lastError, lastErrorAt, consecutiveErrors: errors,
          circuitOpenUntil: circuit ?? (errors === 0 ? null : src.circuitOpenUntil), nextAttemptAt: next, callsDay, callsToday,
          stats: { etag, fetched: rep.result?.fetched ?? null, notModified: rep.result?.notModified ?? false, inserted: rep.result?.inserted ?? null, blocked: rep.result?.blocked ?? null },
        },
      });
    }
    out.push(rep);
  }
  return out;
}
