export type ProbeFailure = "timeout" | "bad-reply" | "no-challenge-answer" | "implausible";

export type A2sProbeResult =
  | { alive: true; rttMs: number; players: number; maxPlayers: number; passworded: boolean; viaSplit: boolean }
  | { alive: false; reason: ProbeFailure };

/**
 * Player-count ceilings: a server claiming more is spoofing the list. A2S carries the counts in one byte
 * (max 255), so Rust's 500-slot servers can only ever report 255; the games below really do run large
 * servers, every other family is held to 128.
 */
const MAX_SLOTS: Record<string, number> = { rust: 255, unturned: 255, projectzomboid: 255 };
export const DEFAULT_MAX_SLOTS = 128;

/** Reject numbers a real server cannot report (spoofed/garbage replies). */
export function plausibleCounts(players: number, maxPlayers: number, game: string): boolean {
  return maxPlayers > 0 && players <= maxPlayers && maxPlayers <= (MAX_SLOTS[game] ?? DEFAULT_MAX_SLOTS);
}

/**
 * Probe one server: request -> (challenge -> request with challenge) -> info. The first send is
 * retried once on silence (UDP loses packets); the second step is not. At most 3 datagrams out.
 */
export async function probeA2s(
  target: { ip: string; port: number; game: string },
  opts: { transport?: A2sTransport; timeoutMs?: number; now?: () => number } = {},
): Promise<A2sProbeResult> {
  const transport = opts.transport ?? udpTransport;
  const timeoutMs = opts.timeoutMs ?? 1500;
  const now = opts.now ?? (() => Date.now());
  const t0 = now();
  let reply = await transport(target.ip, target.port, buildInfoRequest(), timeoutMs);
  if (!reply) reply = await transport(target.ip, target.port, buildInfoRequest(), timeoutMs);
  if (!reply) return { alive: false, reason: "timeout" };
  let parsed = parseA2sResponse(reply);
  if (parsed?.type === "challenge") {
    const second = await transport(target.ip, target.port, buildInfoRequest(parsed.challenge), timeoutMs);
    if (!second) return { alive: false, reason: "no-challenge-answer" };
    parsed = parseA2sResponse(second);
  }
  const rttMs = Math.max(0, now() - t0);
  if (!parsed || parsed.type === "challenge") return { alive: false, reason: "bad-reply" };
  if (parsed.type === "split") return { alive: true, rttMs, players: 0, maxPlayers: 0, passworded: false, viaSplit: true };
  const { players, maxPlayers, passworded } = parsed.info;
  if (!plausibleCounts(players, maxPlayers, target.game)) return { alive: false, reason: "implausible" };
  return { alive: true, rttMs, players, maxPlayers, passworded, viaSplit: false };
}

