export const QUERY_PROTOCOL: Partial<Record<GameFamily, QueryProtocol>> = {
  // Minecraft's two editions, each with its own protocol.
  minecraft: "mc-java",
  bedrock: "bedrock",

  // Source engine — A2S is native, and proven on our own Garry's Mod server.
  cs2: "a2s",
  gmod: "a2s",
  tf2: "a2s",
  l4d2: "a2s",

  // Steam-networking dedicated servers. Each of these registers with Steam's
  // master server list, which requires answering A2S_INFO.
  ark: "a2s",
  arkasa: "a2s",
  rust: "a2s",
  valheim: "a2s",
  vrising: "a2s",
  projectzomboid: "a2s",
