  unturned: "a2s",
  theforest: "a2s",
  sonsoftheforest: "a2s",
  sdtd: "a2s",          // proven live — see the module comment
  enshrouded: "a2s",    // proven live — its queryPort IS its only port
  palworld: "a2s",
  soulmask: "a2s",
  sunkenland: "a2s",
  abioticfactor: "a2s",
  corekeeper: "a2s",
  icarus: "a2s",
  squad: "a2s",
  kf2: "a2s",
  sandstorm: "a2s",
  mordhau: "a2s",
  eco: "a2s",
  barotrauma: "a2s",

  /* Deliberately absent, because no public query protocol exists for them:
     terraria (vanilla and tModLoader expose nothing to a stranger), factorio
     (its multiplayer browser goes through Wube's own matchmaking service, not a
     direct server query), satisfactory (its server API is HTTPS with a bearer
     token), dst, vintagestory, necesse, spaceengineers, empyrion, theisle,
     stationeers, nightingale, dragonwilds, schedule1 and the Plutonium
     families. Those list with their slot count and no live figure — which is
     the honest answer, not a zero. */
};

 */
import { ingestValveGame } from "../lib/directory-ingest/run";
import { VALVE_APPIDS } from "../lib/directory-ingest/valve";

async function main() {
  const arg = (n: string) => { const i = process.argv.indexOf(`--${n}`); return i >= 0 ? process.argv[i + 1] : undefined; };
  const apply = process.argv.includes("--apply");
  const key = process.env.STEAM_WEB_API_KEY;
  if (!key) { console.error("STEAM_WEB_API_KEY is not set (a free Steam Web API key)."); process.exit(2); }
  const games = (arg("game") === "all" ? Object.keys(VALVE_APPIDS).join(",") : arg("game") ?? "valheim,projectzomboid").split(",").map((s) => s.trim()).filter(Boolean);
  const bad = games.filter((g) => !VALVE_APPIDS[g]);
  if (bad.length) { console.error(`Unsupported: ${bad.join(", ")}. Supported: ${Object.keys(VALVE_APPIDS).join(", ")}`); process.exit(2); }
  const limit = arg("limit") ? Number(arg("limit")) : 1000;
  let failed = 0;
  for (const g of games) {
    try {
      const r = await ingestValveGame(g, { apply, key, limit, trigger: "cli" });
      console.log(`${r.dryRun ? "DRY " : "DONE"} ${g}: fetched ${r.fetched}, new ${r.inserted}, updated ${r.updated}, duplicates dropped ${r.duplicates}, blocked (other hosts) ${r.blocked}, pruned ${r.pruned}${r.suspicious ? " (SUSPICIOUS shrink: nothing pruned)" : ""}`);
    } catch (e) {
      failed++;
      console.error(`FAIL ${g}: ${e instanceof Error ? e.message : e}`);
    }
  }
  process.exit(failed ? 1 : 0);
}
main();

