"use client";

import { useState, useTransition } from "react";
import { adminSaveSteamConfig, adminRequestSteamSweep, adminResetSteamBreaker } from "@/lib/actions-listing";

/** Steam legal checkpoints + sweep controls. The two text fields are what the ingest is gated on. */
export function DirectorySteamPanel({ country, reviewedBy, intervalMin }: { country: string; reviewedBy: string; intervalMin: number }) {
  const [c, setC] = useState(country);
  const [by, setBy] = useState(reviewedBy);
  const [iv, setIv] = useState(String(intervalMin));
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const dirty = c !== country || by !== reviewedBy || iv !== String(intervalMin);
  return (
    <div className="card space-y-3 p-4">
      <div>
        <h3 className="text-sm font-semibold">Steam checkpoints and schedule</h3>
        <p className="mt-1 text-xs text-slate-400">
          The Steam ingest, the sweep and showing Steam servers publicly stay blocked until both fields are filled in. The country must be the one named in the privacy policy.
        </p>
      </div>
      <div className="grid gap-3 sm:grid-cols-3">
        <label className="space-y-1 text-xs text-slate-300">Country where Steam data is stored
          <input className="input w-full text-xs" value={c} maxLength={60} onChange={(e) => setC(e.target.value)} placeholder="e.g. Canada" />
        </label>
        <label className="space-y-1 text-xs text-slate-300">Who read the Steam Web API terms (name, date)
          <input className="input w-full text-xs" value={by} maxLength={120} onChange={(e) => setBy(e.target.value)} placeholder="name, YYYY-MM-DD" />
        </label>
        <label className="space-y-1 text-xs text-slate-300">Minutes between refreshes of one game (30 to 1440)
          <input className="input w-full text-xs" type="number" min={30} max={1440} value={iv} onChange={(e) => setIv(e.target.value)} />
        </label>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <button className="btn-primary py-1 text-xs" disabled={pending || !dirty} onClick={() => start(async () => {
          const r = await adminSaveSteamConfig({ storageCountry: c, termsReviewedBy: by, intervalMin: Number(iv) });
          setMsg(r.ok ? "Saved. Reload to see the status." : r.error);
        })}>Save</button>
        <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => start(async () => {
          const r = await adminRequestSteamSweep();
          setMsg(r.ok ? "Requested: the worker refreshes every game on its next tick if the sweep is on and nothing blocks it." : r.error);
        })}>Run sweep now</button>
        <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => start(async () => {
          const r = await adminResetSteamBreaker();
          setMsg(r.ok ? "Breaker and backoff cleared." : r.error);
        })}>Reset breaker</button>
        {msg && <span className="text-xs text-slate-300">{msg}</span>}
      </div>
    </div>
  );
}
