 * Directory v2 sources: the Steam extra-family list and, per non-Steam source, its terms reviewer and enable switch.
 * A source can only be switched on when a reviewer is recorded (the legal checkpoint made mechanical); every
 * source is default OFF. Turning one off also clears nothing: its rows age out under the source's own prune rule.
 */
export async function adminSaveSourcesConfig(input: { steamExtraGames: string; providers: Record<string, { enabled: boolean; reviewedBy: string }> }): Promise<Result> {
  const admin = await requireArea("fleet");
  const { setSetting } = await import("./settings");
  const { STEAM_EXTRA_APPIDS } = await import("./directory-ingest/valve");
  const { PROVIDERS } = await import("./directory-ingest/providers/registry");
  const { enableSettingFor, reviewedSettingFor } = await import("./directory-ingest/providers/types");
  const extra = [...new Set(String(input.steamExtraGames ?? "").split(",").map((g) => g.trim().toLowerCase()).filter(Boolean))];
  const unknown = extra.filter((g) => !STEAM_EXTRA_APPIDS[g]);
  if (unknown.length) return { ok: false, error: `Unknown Steam families: ${unknown.join(", ")}. Known: ${Object.keys(STEAM_EXTRA_APPIDS).join(", ")}.` };
  for (const p of PROVIDERS) {
    const v = input.providers?.[p.key];
    if (!v) continue;
    const by = String(v.reviewedBy ?? "").replace(/\\s+/g, " ").trim();
    if (by.length > 120) return { ok: false, error: "Reviewer text too long." };
    if (v.enabled && !by) return { ok: false, error: `${p.label}: record who read its terms (${p.termsUrl}) before switching it on.` };
  }
  await setSetting("directory_steam_extra_games", extra.join(","));
  for (const p of PROVIDERS) {
    const v = input.providers?.[p.key];
    if (!v) continue;
    await setSetting(reviewedSettingFor(p.key), String(v.reviewedBy ?? "").replace(/\\s+/g, " ").trim());
    await setSetting(enableSettingFor(p.key), v.enabled ? "true" : "false");
  }
  await recordAudit(admin.id, "directory.sources.config", `steamExtra=${extra.join(",") || "-"} ${PROVIDERS.map((p) => `${p.key}=${input.providers?.[p.key]?.enabled ? "on" : "off"}`).join(" ")}`);
  revalidatePath("/admin/directory");
  return { ok: true };
}

