export type SourceRow = { key: string; label: string; games: string; termsUrl: string; enabled: boolean; reviewedBy: string; status: string };

/** Directory v2 sources: extra Steam families and the per-source terms checkpoint + switch (all default off). */
export function DirectorySourcesPanel({ steamExtra, steamKnown, sources }: { steamExtra: string; steamKnown: string[]; sources: SourceRow[] }) {
