import { sweepGames, STEAM_EXTRA_APPIDS, VALVE_APPIDS, ALL_STEAM_APPIDS } from "../lib/directory-ingest/valve";

const fx = (n: string) => JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures/directory", n), "utf8"));
const rules = buildRuleSet().set;
