test("vintage story: only open (no password, not whitelisted) servers are parsed from a real sample", () => {
  const c = parseVsResponse(fx("vintagestory-sample.json"));
  assert.ok(c.length >= 4, `parsed ${c.length}`);
  for (const r of c) {
    assert.equal(r.game, "vintagestory");
    assert.equal(r.alive, true);
    assert.ok(r.port > 1023);
    assert.ok(r.name.length >= 3);
    assert.ok(r.players === null || r.maxPlayers === null || r.players <= r.maxPlayers);
  }
  // password and whitelist rows from the fixture are dropped
  const raw = fx("vintagestory-sample.json").data as { hasPassword: boolean; whitelisted: boolean }[];
  assert.ok(raw.some((r) => r.hasPassword) && raw.some((r) => r.whitelisted));
  assert.ok(c.length < raw.length);
});

test("vintage story: hostnames kept, IPv6 and private/odd addresses refused, spoofed counts refused", () => {
  assert.deepEqual(parseVsAddress("tops.vintagestory.at:42420"), { host: "tops.vintagestory.at", ip: null, port: 42420 });
  assert.equal(parseVsAddress("[2a01:e0a:11a1::1]:42420"), null);
  assert.equal(parseVsAddress("10.0.0.5:42420"), null);
  assert.equal(parseVsAddress("192.168.1.2:42420"), null);
  assert.equal(parseVsAddress("localhost:42420"), null);
  assert.equal(parseVsAddress("1.2.3.4:22"), null);
  assert.equal(parseVsAddress("1.2.3.4:0"), null);
  const ok = { serverName: "Open World", serverIP: "8.8.4.4:42420", maxPlayers: "16", players: 2, hasPassword: false, whitelisted: false, gameVersion: "1.20.11", playstyle: { id: "surviveandbuild" } };
  assert.equal(parseVsRow(ok)?.maxPlayers, 16);
  assert.deepEqual(parseVsRow(ok)?.tags, ["surviveandbuild"]);
  assert.equal(parseVsRow({ ...ok, players: 40 }), null);
  assert.equal(parseVsRow({ ...ok, maxPlayers: "0" }), null);
  assert.equal(parseVsRow({ ...ok, serverName: "  " }), null);
  assert.equal(parseVsRow({ ...ok, hasPassword: true }), null);
  assert.equal(parseVsRow({ ...ok, whitelisted: true }), null);
  assert.equal(parseVsRow({ ...ok, hasPassword: undefined }), null); // unknown = not provably open
});

test("truckersmp: ETS2/ATS rows parsed from a real sample, online flag carried, bad rows dropped", () => {
  const c = parseTmpResponse(fx("truckersmp-sample.json"));
  assert.equal(c.length, 4);
  assert.ok(c.every((r) => r.game === "ets2" && r.alive === true && r.tags.includes("official") && r.name.startsWith("TruckersMP ")));
  const base = { id: 1, game: "ATS", ip: "8.8.8.8", port: 27015, name: "US 1", online: false, players: 5, maxplayers: 10 };
  assert.equal(parseTmpRow(base)?.game, "ats");
  assert.equal(parseTmpRow(base)?.alive, false);
  assert.equal(parseTmpRow({ ...base, game: "XYZ" }), null);
  assert.equal(parseTmpRow({ ...base, ip: "10.1.1.1" }), null);
  assert.equal(parseTmpRow({ ...base, players: 99 })?.players, null);
});

test("probe kind per family: right protocol, listing sources never probed", () => {
  assert.equal(probeKindForGame("minecraft"), "slp");
  assert.equal(probeKindForGame("bedrock"), "raknet");
  assert.equal(probeKindForGame("valheim"), "a2s");
  assert.equal(probeKindForGame("rust"), "a2s");
  assert.equal(probeKindForGame("vintagestory"), "listing");
  assert.equal(probeKindForGame("ets2"), "listing");
  assert.equal(probeKindForGame("terraria"), null);
  assert.equal(probeKindForGame("factorio"), null);
});

test("probeByKind: slp/raknet use their pinger, 'listing' sends nothing, failures are not-alive", async () => {
  const t = { ip: "8.8.8.8", port: 25565, game: "minecraft" };
  let calls = 0;
  const slp = async () => { calls++; return { online: 3, max: 20, motd: "x", map: null }; };
  const a = await probeByKind("slp", t, { slp });
  assert.ok(a.alive && a.players === 3 && a.maxPlayers === 20);
  const b = await probeByKind("raknet", { ...t, port: 19132, game: "bedrock" }, { raknet: async () => null });
  assert.deepEqual(b, { alive: false, reason: "timeout" });
  const c = await probeByKind("slp", t, { slp: async () => { throw new Error("boom"); } });
  assert.equal(c.alive, false);
  const d = await probeByKind("slp", t, { slp: async () => ({ online: 99, max: 20, motd: null, map: null }) });
  assert.deepEqual(d, { alive: false, reason: "implausible" });
  const n = calls;
  const e = await probeByKind("listing", t, { slp });
  assert.deepEqual(e, { alive: false, reason: "no-probe" });
  assert.equal(calls, n);
});

test("politeGetJson: honest UA, ETag 304, status+Retry-After surfaced, size cap, bad JSON", async () => {
  let seen: Record<string, string> = {};
  const mk = (res: Partial<Response> & { body?: string }) => (async (_u: unknown, init: RequestInit) => {
    seen = init.headers as Record<string, string>;
    return { status: res.status ?? 200, ok: (res.status ?? 200) < 400, headers: new Headers(res.headers), text: async () => res.body ?? "{}" } as Response;
  }) as unknown as typeof fetch;
  const ok = await politeGetJson("https://x.test/a", { fetchImpl: mk({ headers: { etag: '"abc"' } as never, body: '{"a":1}' }), etag: '"old"' });
  assert.equal(seen["user-agent"], DIRECTORY_UA);
  assert.match(DIRECTORY_UA, /nxeon\.cloud/);
  assert.equal(seen["if-none-match"], '"old"');
  assert.equal(ok.etag, '"abc"');
  const nm = await politeGetJson("https://x.test/a", { fetchImpl: mk({ status: 304 }), etag: '"old"' });
  assert.equal(nm.notModified, true);
  await assert.rejects(politeGetJson("https://x.test/a", { fetchImpl: mk({ status: 429, headers: { "retry-after": "120" } as never }) }), (e: unknown) => e instanceof ProviderFetchError && e.status === 429 && e.retryAfterSec === 120);
  await assert.rejects(politeGetJson("https://x.test/a", { fetchImpl: mk({ body: "<html>" }) }), /not JSON/);
  await assert.rejects(politeGetJson("https://x.test/a", { fetchImpl: mk({ body: "x".repeat(50) }), maxBytes: 10 }), /too large/);
});

test("providers: fetch() goes through the one request path and handles 304", async () => {
