}) as unknown as typeof fetch;

async function mods() {
  const { db } = await import("../lib/db");
  const { setSetting, getSettingBool } = await import("../lib/settings");
  const run = await import("../lib/directory-ingest/provider-run");
  const prober = await import("../lib/directory-ingest/prober");
  const data = await import("../lib/server-directory-data");
  const vs = await import("../lib/directory-ingest/providers/vintagestory");
  const tm = await import("../lib/directory-ingest/providers/truckersmp");
  return { db, setSetting, getSettingBool, ...run, ...prober, ...data, vs: vs.vintageStoryProvider, tm: tm.truckersMpProvider };
}
async function reset(m: Awaited<ReturnType<typeof mods>>) {
  await m.db.externalServer.deleteMany(); await m.db.directoryIngestRun.deleteMany(); await m.db.directorySource.deleteMany(); await m.db.setting.deleteMany();
}

T("default OFF: nothing is fetched or written, even with ingest on, until enabled AND reviewed", async () => {
  const m = await mods(); await reset(m);
  let calls = 0;
  const f = (async () => { calls++; return { status: 200, ok: true, headers: new Headers(), text: async () => fx("vintagestory-sample.json") } as Response; }) as unknown as typeof fetch;
  await m.setSetting("directory_ingest_enabled", "true");
  assert.equal((await m.directoryProviderTick({ now: NOW, fetchImpl: f, reverse }))[0].skipped, "disabled");
  await m.setSetting("directory_src_vintagestory_enabled", "true");
  const r = await m.directoryProviderTick({ now: NOW, fetchImpl: f, reverse });
  assert.equal(r.find((x) => x.key === "vintagestory")?.skipped, "not-reviewed");
  assert.equal(calls, 0);
  assert.equal(await m.db.externalServer.count(), 0);
});

T("enabled + reviewed: rows stored with attribution, listing liveness, honest freshness; then not-due; then 304 keeps rows", async () => {
  const m = await mods(); await reset(m);
  await m.setSetting("directory_ingest_enabled", "true"); await m.setSetting("directory_external_show", "true");
  await m.setSetting("directory_src_vintagestory_enabled", "true"); await m.setSetting("directory_src_vintagestory_reviewed_by", "Test Owner 2026-10-05");
  const only = [m.vs];
  const f = serve(fx("vintagestory-sample.json"), { etag: '"v1"' });
  const a = (await m.directoryProviderTick({ now: NOW, fetchImpl: f, reverse, providers: only }))[0];
  assert.ok(a.result && a.result.fetched >= 3 && a.result.inserted === a.result.fetched, JSON.stringify(a));
  const rows = await m.db.externalServer.findMany({ where: { source: "vintagestory" } });
  assert.ok(rows.length >= 3);
  assert.ok(rows.every((r) => r.attribution === "vintagestory" && r.probeKind === "listing" && r.probeStatus === "ALIVE" && r.game === "vintagestory"));
  // second tick inside the interval does nothing
  assert.equal((await m.directoryProviderTick({ now: NOW + 5 * 60_000, fetchImpl: f, reverse, providers: only }))[0].skipped, "not-due");
  // after the interval, revalidation answers 304: rows stay, nothing rewritten
  const b = (await m.directoryProviderTick({ now: NOW + 35 * 60_000, fetchImpl: f, reverse, providers: only }))[0];
  assert.equal(b.result?.notModified, true);
  assert.equal(await m.db.externalServer.count({ where: { source: "vintagestory" } }), rows.length);
  // public directory: shown with attribution, never "checked" (that word is for OUR direct query)
  const { entries } = await m.loadDirectory({ game: "vintagestory" });
  assert.equal(entries.length, rows.length);
  assert.ok(entries.every((e) => e.attribution === "vintagestory" && e.checkedAt === null && e.source === "external"));
  // switch off => hidden, with no re-ingest
  await m.setSetting("directory_external_show", "false");
  assert.equal((await m.loadDirectory({ game: "vintagestory" })).entries.length, 0);
});

T("failure backs off; repeated failure opens the breaker; 403 switches the source OFF; sources are independent", async () => {
  const m = await mods(); await reset(m);
  await m.setSetting("directory_ingest_enabled", "true");
  for (const k of ["truckersmp", "vintagestory"]) { await m.setSetting(`directory_src_${k}_enabled`, "true"); await m.setSetting(`directory_src_${k}_reviewed_by`, "T"); }
  const bad = serve("oops", { status: 503 });
  const r1 = await m.directoryProviderTick({ now: NOW, fetchImpl: bad, reverse, providers: [m.tm] });
  assert.match(r1[0].error ?? "", /503/);
  const s1 = await m.db.directorySource.findUnique({ where: { key: "truckersmp" } });
  assert.equal(s1?.consecutiveErrors, 1); assert.ok(s1!.nextAttemptAt && s1!.nextAttemptAt.getTime() > NOW);
  assert.equal((await m.directoryProviderTick({ now: NOW + 60_000, fetchImpl: bad, reverse, providers: [m.tm] }))[0].skipped, "backoff");
  // a different source is unaffected by this one's backoff
  const ok = await m.directoryProviderTick({ now: NOW, fetchImpl: serve(fx("vintagestory-sample.json")), reverse, providers: [m.vs] });
  assert.ok(ok[0].result);
  // 403: switched off and breaker open
  await m.db.directorySource.update({ where: { key: "truckersmp" }, data: { nextAttemptAt: null } });
  const r403 = await m.directoryProviderTick({ now: NOW + 2 * 3600_000, fetchImpl: serve("no", { status: 403 }), reverse, providers: [m.tm] });
  assert.equal(r403[0].disabled, true);
  assert.equal(await m.getSettingBool("directory_src_truckersmp_enabled", true), false);
  const s2 = await m.db.directorySource.findUnique({ where: { key: "truckersmp" } });
  assert.ok(s2!.circuitOpenUntil && s2!.circuitOpenUntil.getTime() > NOW);
});

T("steam row wins over a later listing row for the same connection; prune and suspicious-shrink protection", async () => {
  const m = await mods(); await reset(m);
  await m.setSetting("directory_ingest_enabled", "true");
  await m.setSetting("directory_src_truckersmp_enabled", "true"); await m.setSetting("directory_src_truckersmp_reviewed_by", "T");
  const body = fx("truckersmp-sample.json");
  const first = JSON.parse(body).response[0];
  await m.db.externalServer.create({ data: { source: "valve", sourceKey: `${first.ip}:${first.port}`, game: "ets2", name: "Steam row", host: first.ip, ip: first.ip, port: first.port, connKey: `${first.ip}:${first.port}`, ipKey: `${first.ip}:${first.port}`, tags: [] } });
  const r = (await m.directoryProviderTick({ now: NOW, fetchImpl: serve(body), reverse, providers: [m.tm] }))[0];
  assert.equal(r.result?.duplicates, 1);
  assert.equal(await m.db.externalServer.count({ where: { source: "truckersmp" } }), 3);
  // a source that stopped listing a row: pruned after pruneAfterDays (1 day)
  await m.db.externalServer.updateMany({ where: { source: "truckersmp" }, data: { lastSeenAt: new Date(NOW - 3 * 86_400_000) } });
  await m.db.directorySource.update({ where: { key: "truckersmp" }, data: { lastOkAt: new Date(NOW - 3 * 86_400_000) } });
  const one = JSON.stringify({ response: [JSON.parse(body).response[1]] });
  const r2 = (await m.directoryProviderTick({ now: NOW + 3600_000, fetchImpl: serve(one), reverse, providers: [m.tm] }))[0];
  assert.equal(r2.result?.pruned, 2);
});

T("prober: minecraft rows are probed over SLP, bedrock over RakNet; listing rows are never probed", async () => {
  const m = await mods(); await reset(m);
