  const mc = await m.db.externalServer.findFirst({ where: { sourceKey: "mc" } });
  assert.equal(mc?.probeStatus, "ALIVE"); assert.equal(mc?.players, 3);
  assert.equal((await m.db.externalServer.findFirst({ where: { sourceKey: "ls" } }))?.lastProbeAt, null);
});
